// ── Same Zoom challenge/validation pattern as the attendee workflow ──
const body = $input.first().json.body || $input.first().json;

const isValidation = body.event === 'endpoint.url_validation';
const plainToken = body?.payload?.plainToken || '';

let encryptedToken = '';
if (isValidation) {
  const crypto = require('crypto');
  // ⚠️ Replace with your Zoom App Secret Token (same as attendee workflow)
  const secretToken = '8uEUEC7-Tf-wDkU2WKBdRA';
  encryptedToken = crypto
    .createHmac('sha256', secretToken)
    .update(plainToken)
    .digest('hex');
}

return [{ json: { isValidation, plainToken, encryptedToken, originalBody: body } }];

const body = $('Code: Handle Zoom Challenge').first().json.originalBody;
const eventType = body.event || '';
const payload = body.payload || {};
const obj = payload.object || {};

return [{
  json: {
    event_type: eventType,
    is_webinar_ended: eventType === 'webinar.ended',
    webinar_id: String(obj.id || ''),
    webinar_topic: obj.topic || '',
    host_id: obj.host_id || '',
    start_time: obj.start_time || '',
    duration: obj.duration || 0
  }
}];

// ════════════════════════════════════════════════════════════
// POST-WEBINAR GROUP BUILDER
// Fetches all Zoom participants + registrants (with pagination),
// cross-references them, and returns two groups:
//   group: 'attended_no_call'  → Sequence A
//   group: 'no_show'           → Sequence B
// ════════════════════════════════════════════════════════════

// ⚠️ FILL IN YOUR KIT SEQUENCE IDs BELOW
const SEQUENCE_A_ID = 'YOUR_SEQUENCE_A_ID';   // Attended, did NOT book a call
const SEQUENCE_B_ID = 'YOUR_SEQUENCE_B_ID';   // Registered but didn't show up

const eventData = $('Code: Parse Event').item.json;
const accessToken = $input.first().json.access_token;
const webinarId = eventData.webinar_id;

if (!accessToken) throw new Error('No Zoom access token received — check your Server-to-Server OAuth credential.');
if (!webinarId) throw new Error('No webinar ID in event payload.');

// ── Helper: fetch all pages from a Zoom API endpoint ────────
async function fetchAllPages(baseUrl, itemsKey) {
  let allItems = [];
  let nextPageToken = '';
  let page = 0;

  do {
    const sep = baseUrl.includes('?') ? '&' : '?';
    const url = nextPageToken
      ? `${baseUrl}${sep}next_page_token=${encodeURIComponent(nextPageToken)}`
      : baseUrl;

    let response;
    try {
      response = await $http.request({
        method: 'GET',
        url,
        headers: { 'Authorization': `Bearer ${accessToken}` }
      });
    } catch (err) {
      // Log and stop pagination on error (don't fail entire workflow)
      console.error(`Zoom API error on page ${page} for ${baseUrl}: ${err.message}`);
      break;
    }

    const items = response[itemsKey] || [];
    allItems = allItems.concat(items);
    nextPageToken = response.next_page_token || '';
    page++;

    if (page >= 30) {
      console.warn(`Safety limit hit at 30 pages (${allItems.length} items) for ${baseUrl}`);
      break;
    }
  } while (nextPageToken);

  return allItems;
}

// ── 1. Fetch everyone who actually attended (Zoom Reports API) ──
//    Requires scope: report:read:admin
const participants = await fetchAllPages(
  `https://api.zoom.us/v2/report/webinars/${webinarId}/participants?page_size=300`,
  'participants'
);

// ── 2. Fetch everyone who registered (including no-shows) ──
//    Requires scope: webinar:read:admin
const registrants = await fetchAllPages(
  `https://api.zoom.us/v2/webinars/${webinarId}/registrants?page_size=300&status=approved`,
  'registrants'
);

console.log(`Zoom data: ${participants.length} participants, ${registrants.length} registrants for webinar ${webinarId}`);

// ── 3. Build Set of attended emails ──────────────────────────
const attendedSet = new Set(
  participants
    .map(p => (p.user_email || p.email || '').toLowerCase().trim())
    .filter(e => e !== '')
);

// ── 4. Build output items ─────────────────────────────────────
const seen = new Set();
const output = [];

// Group A: Attended (no-call booking — Kit sequence conditions
// or manual removal handles people who already booked a call)
for (const p of participants) {
  const email = (p.user_email || p.email || '').toLowerCase().trim();
  if (!email || seen.has(email)) continue;
  seen.add(email);
  const fullName = (p.name || p.user_name || '').trim();
  output.push({
    json: {
      email,
      first_name: fullName.split(' ')[0] || '',
      full_name: fullName,
      group: 'attended_no_call',
      sequence_id: SEQUENCE_A_ID
    }
  });
}

// Group B: No-shows (registered but never joined)
for (const r of registrants) {
  const email = (r.email || '').toLowerCase().trim();
  if (!email || attendedSet.has(email) || seen.has(email)) continue;
  seen.add(email);
  const fullName = `${r.first_name || ''} ${r.last_name || ''}`.trim();
  output.push({
    json: {
      email,
      first_name: r.first_name || '',
      full_name: fullName,
      group: 'no_show',
      sequence_id: SEQUENCE_B_ID
    }
  });
}

const attendedCount = output.filter(i => i.json.group === 'attended_no_call').length;
const noShowCount = output.filter(i => i.json.group === 'no_show').length;
console.log(`✅ Groups built: ${attendedCount} attended-no-call, ${noShowCount} no-shows. Total to enroll: ${output.length}`);

// Return a sentinel if nobody to enroll (prevents downstream errors)
if (output.length === 0) {
  return [{ json: { group: '__empty__', email: '', sequence_id: '', first_name: '', full_name: '' } }];
}

return output;
